<?php
namespace App\Jobs;use App\Models\Booking;use App\Services\WhatsAppGateway;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Log;use Illuminate\Support\Facades\Mail;use Illuminate\Support\Facades\URL;
class DispatchBookingNotifications implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public int $bookingId){}public function handle(WhatsAppGateway $wa):void{$b=Booking::with(['facility','payment','invoice'])->find($this->bookingId);if(!$b||!$b->invoice)return;$url=URL::temporarySignedRoute('invoices.public',now()->addDays(7),['invoice'=>$b->invoice->uuid]);try{Mail::to($b->customer_email)->send(new \App\Mail\BookingInvoiceMail($b));}catch(\Throwable $e){Log::error('booking invoice email failed',['booking_id'=>$b->id,'error'=>$e->getMessage()]);}try{$wa->sendMessage($b->customer_phone,"Pembayaran berhasil. Booking {$b->booking_number} telah dikonfirmasi.\nInvoice: {$b->invoice->invoice_number}\n{$url}");$wa->sendPdf($b->customer_phone,'Invoice '.$b->invoice->invoice_number.' - '.$b->facility->name,$url);}catch(\Throwable $e){Log::error('booking invoice whatsapp failed',['booking_id'=>$b->id,'error'=>$e->getMessage()]);}}}
